function examField(string $name,string $label,string $type='text',array $options=[],bool $required=true,mixed $default=''):void{
 $value=$_POST[$name]??$default;echo '<label>'.e($label).($required?' *':'');if($type==='select'){echo '<select name="'.e($name).'" '.($required?'required':'').'><option value="">Select…</option>';foreach($options as $k=>$v){$key=array_is_list($options)?$v:$k;echo '<option value="'.e($key).'" '.((string)$key===(string)$value?'selected':'').'>'.e($v).'</option>';}echo '</select>';}else echo '<input name="'.e($name).'" type="'.e($type).'" '.($type==='file'?'accept="application/pdf,.pdf"':'value="'.e($value).'"').' '.($required?'required':'').'>';echo '</label>';
}
function examForm(string $action,int $wid=0):void{echo '<form method="post" enctype="multipart/form-data">';csrf();echo '<input type="hidden" name="action" value="'.e($action).'"><input type="hidden" name="window_id" value="'.$wid.'">';}
